//! "About" and legal commands: the bundled third-party licence notices
//! (Settings → Sources → "Full third-party notices").
//!
//! The notices are generated by `scripts/gen-third-party-licenses.mjs` into
//! `src-tauri/licenses/` and bundled through `bundle.resources` in
//! `tauri.conf.json`. The frontend asks for one by a fixed `kind`, checked
//! against an allowlist, so it can never name an arbitrary path.

use tauri::Manager;

use crate::errors::InkyCapError;

/// The app's version (e.g. `26.6.1`), from the version Tauri was built with
/// (`tauri.conf.json`, kept in step with `Cargo.toml` by
/// `scripts/version.mjs`). It's `YY.MM.RELEASE`; RELEASE is even for
/// user-facing releases and odd for development builds (shown in Settings →
/// Overview).
#[tauri::command]
pub fn app_version(app: tauri::AppHandle) -> String {
    app.package_info().version.to_string()
}

/// Map a frontend `kind` to its bundled filename. The allowlist is the trust
/// boundary: `kind` is never interpolated into a path beyond these constants.
fn notices_filename(kind: &str) -> Result<&'static str, InkyCapError> {
    match kind {
        "rust" => Ok("THIRD-PARTY-rust.txt"),
        "js" => Ok("THIRD-PARTY-js.txt"),
        other => Err(InkyCapError::InvalidPath(format!(
            "Unknown third-party notices kind: {other}"
        ))),
    }
}

/// Read a bundled licence notices file and return its text. Packaged builds
/// have it in the resource folder; `tauri dev` doesn't stage resources, so it
/// falls back to the source tree (`CARGO_MANIFEST_DIR`). The file always comes
/// from a fixed allowlist.
#[tauri::command]
pub async fn read_third_party_notices(
    kind: String,
    app: tauri::AppHandle,
) -> Result<String, InkyCapError> {
    let rel = format!("licenses/{}", notices_filename(&kind)?);

    // Packaged build: resolve against the bundled resource directory.
    if let Ok(path) = app
        .path()
        .resolve(&rel, tauri::path::BaseDirectory::Resource)
    {
        if path.is_file() {
            return Ok(std::fs::read_to_string(&path)?);
        }
    }

    // Dev fallback: read straight from the source tree.
    let dev_path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(&rel);
    if dev_path.is_file() {
        return Ok(std::fs::read_to_string(&dev_path)?);
    }

    Err(InkyCapError::InvalidPath(format!(
        "Third-party notices file not found: {rel}"
    )))
}
